<?php
declare(strict_types=1);
namespace RetroWEB\Rendering;
use RetroWEB\Application\{DocumentRenderer,RenderRequest};use RetroWEB\Domain\Profile\{ProfileDetector,ProfileRepository};use RetroWEB\Domain\Settings\{SettingsResolver,SettingsOverrides};use RetroWEB\Infrastructure\Persistence\FileSettingsRepository;use RetroWEB\Rendering\Extraction\ExtractionStrategy;use RetroWEB\Rendering\Transform\LegacyTransformer;use RetroWEB\Rendering\Pagination\MemoryBudgetPaginator;

final class ProfileAwareRenderer implements DocumentRenderer
{
    public function __construct(private ProfileDetector$detector,private ProfileRepository$profiles,private FileSettingsRepository$settings,private ExtractionStrategy$extractor,private LegacyTransformer$transformer,private MemoryBudgetPaginator$paginator){}
    public function render(string$html,string$sourceUrl,RenderRequest$request):array{$detection=$this->detector->detect($request->userAgent);$now=time();$state=$request->clientIdentity!==null?$this->settings->loadState($request->clientIdentity,$now):null;$saved=$state[0]??new SettingsOverrides();$profileId=$saved->selectedProfile!==null&&$this->profiles->has($saved->selectedProfile)?$saved->selectedProfile:$detection->profileId;$profile=$this->profiles->get($profileId);$custom=$profileId==='generic'||($state[1]??false);try{$effective=(new SettingsResolver())->resolve($profile,$saved,$custom)->values;}catch(\InvalidArgumentException){$saved=new SettingsOverrides([],in_array($saved->imageMode,['inline','links'],true)?$saved->imageMode:null,$saved->selectedProfile);if($request->clientIdentity!==null)$this->settings->save($request->clientIdentity,$saved,$now,$custom);$effective=(new SettingsResolver())->resolve($profile,$saved,$custom)->values;}$imageWidth=min($effective['image_width'],$effective['viewport_width']);$imageHeight=min($effective['image_height'],$effective['viewport_height']);$renderer=new LegacyDocumentRenderer($this->extractor,$this->transformer,$this->paginator,$effective['html'],$effective['page_budget_kb']*1024,2048,$effective['delivery']==='unsplit',$effective['image_mode'],$imageWidth,$imageHeight,$effective['viewport_width'],$profile->capabilities,$profile->workarounds);return$renderer->render($html,$sourceUrl,$request);}
    public function encoding(RenderRequest$request):string{$detection=$this->detector->detect($request->userAgent);$state=$request->clientIdentity!==null?$this->settings->loadState($request->clientIdentity,time()):null;$saved=$state[0]??new SettingsOverrides();$profileId=$saved->selectedProfile!==null&&$this->profiles->has($saved->selectedProfile)?$saved->selectedProfile:$detection->profileId;return$this->profiles->get($profileId)->encoding;}
}
